CREATE SCHEMA IF NOT EXISTS rotom;
SET search_path TO rotom, public;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,name TEXT NOT NULL,password_hash TEXT NOT NULL,catalog_admin BIGINT NOT NULL DEFAULT 0,created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS campaigns(id TEXT PRIMARY KEY,name TEXT NOT NULL,owner_id TEXT NOT NULL REFERENCES users(id),created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS memberships(campaign_id TEXT NOT NULL REFERENCES campaigns(id),user_id TEXT NOT NULL REFERENCES users(id),role TEXT NOT NULL CHECK(role IN ('gm','player')),PRIMARY KEY(campaign_id,user_id));
CREATE TABLE IF NOT EXISTS invites(token_hash TEXT PRIMARY KEY,campaign_id TEXT NOT NULL REFERENCES campaigns(id),expires_at BIGINT NOT NULL,remaining_uses BIGINT NOT NULL CHECK(remaining_uses>=0));
CREATE TABLE IF NOT EXISTS characters(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id),campaign_id TEXT REFERENCES campaigns(id),kind TEXT NOT NULL CHECK(kind IN ('player','npc')),name TEXT NOT NULL,data_json TEXT NOT NULL,version BIGINT NOT NULL DEFAULT 1,updated_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS assets(id TEXT PRIMARY KEY,mime TEXT NOT NULL,data BYTEA NOT NULL);
CREATE TABLE IF NOT EXISTS revisions(id TEXT PRIMARY KEY,character_id TEXT NOT NULL REFERENCES characters(id),actor_id TEXT NOT NULL REFERENCES users(id),action TEXT NOT NULL,before_json TEXT NOT NULL,patch_json TEXT NOT NULL,created_at BIGINT NOT NULL,expires_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS revisions_character ON revisions(character_id,created_at);
CREATE INDEX IF NOT EXISTS revisions_expiry ON revisions(expires_at);
CREATE TABLE IF NOT EXISTS catalog_entries(id TEXT PRIMARY KEY,kind TEXT NOT NULL,source_key TEXT,official_json TEXT NOT NULL DEFAULT '{}',translations_json TEXT NOT NULL DEFAULT '{}',rpg_json TEXT NOT NULL DEFAULT '{}',version BIGINT NOT NULL DEFAULT 1,updated_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS catalog_staging(id TEXT PRIMARY KEY,source TEXT NOT NULL,rows_json TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS catalog_import_meta(batch_id TEXT PRIMARY KEY REFERENCES catalog_staging(id),fingerprint TEXT NOT NULL,applied_at BIGINT);
CREATE TABLE IF NOT EXISTS catalog_review(entry_id TEXT PRIMARY KEY REFERENCES catalog_entries(id),official_status TEXT NOT NULL DEFAULT 'pending' CHECK(official_status IN ('pending','reviewed')),translation_status TEXT NOT NULL DEFAULT 'pending' CHECK(translation_status IN ('pending','draft','reviewed')),rpg_status TEXT NOT NULL DEFAULT 'pending' CHECK(rpg_status IN ('pending','draft','reviewed')));
CREATE TABLE IF NOT EXISTS catalog_candidates(entry_id TEXT PRIMARY KEY REFERENCES catalog_entries(id),batch_id TEXT NOT NULL REFERENCES catalog_staging(id),data_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS catalog_batch_issues(batch_id TEXT PRIMARY KEY REFERENCES catalog_staging(id),issues_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS archived_characters(character_id TEXT PRIMARY KEY REFERENCES characters(id),archived_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS app_meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
